function maxSum(nums) {
  const bestByDigit = new Map();
  let answer = -1;
  for (const num of nums) {
    let digit = 0;
    let rest = num;
    while (rest > 0) {
      digit = Math.max(digit, rest % 10);
      rest = Math.floor(rest / 10);
    }
    if (bestByDigit.has(digit)) {
      answer = Math.max(answer, bestByDigit.get(digit) + num);
      bestByDigit.set(digit, Math.max(bestByDigit.get(digit), num));
    } else {
      bestByDigit.set(digit, num);
    }
  }
  return answer;
}

