function maxSum(nums) {
  const top = value => Math.max(...String(value).split('').map(Number));
  let result = -1;
  for (let i = 0; i < nums.length; i++)
    for (let j = i + 1; j < nums.length; j++)
      if (top(nums[i]) === top(nums[j])) result = Math.max(result, nums[i] + nums[j]);
  return result;
}

