function generate(rand, size) {
  const n = size === 'large' ? 100 : 2 + Math.floor(rand() * 7);
  const limits = [9, 99, 999, 10000];
  const limit = limits[Math.floor(rand() * limits.length)];
  const nums = [];
  for (let i = 0; i < n; i++) {
    const cap = size === 'large' ? 10000 : limit;
    nums.push(1 + Math.floor(rand() * cap));
  }
  return [nums];
}
